namespace RideFixBro.API.Tests
{
	internal static class ImageFixtures
	{
		private const string PngBase64 =
			"iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR4nGNgYPj/HwADAgH/5ncLrgAAAABJRU5ErkJggg==";

		public static byte[] Png(int? totalBytes = null)
		{
			var image = Convert.FromBase64String(PngBase64);
			if (totalBytes is not null)
			{
				// Padding tests file-byte limits without generating a large picture.
				Array.Resize(ref image, totalBytes.Value);
			}
			return image;
		}

		public static byte[] PngWithOversizedDimensions()
		{
			// A 4097 x 4096 header must be rejected before attempting to decode its pixels.
			return Convert.FromBase64String(
				"iVBORw0KGgoAAAANSUhEUgAAEAEAABAACAYAAAAdYU8pAAAADUlEQVR4nGNgYPj/HwADAgH/5ncLrgAAAABJRU5ErkJggg==");
		}

		public const string JpegBase64 =
			"";
	}
}
